# R6M 策略资产：停止并禁用服务 RemoteRegistry
# 为什么用 ps1 而不是等注册表 Start 值：改 Start 值要**下次开机**才生效，
# 而这里当场 Stop-Service 并 Set-Service Disabled —— 立刻有效、重启后也不复活。
$n = 'RemoteRegistry'
$ErrorActionPreference = 'Continue'
$ok = $true
try {
    Stop-Service -Name $n -Force -ErrorAction Stop
    Write-Output "stopped $n"
} catch {
    # 服务本来就没在跑不算失败（目标已达成）
    Write-Output "stop: $($_.Exception.Message)"
}
try {
    Set-Service -Name $n -StartupType Disabled -ErrorAction Stop
    Write-Output "disabled $n"
} catch {
    Write-Output "disable FAILED: $($_.Exception.Message)"
    $ok = $false
}
# 只有"禁用"失败才返回非 0：那才是需要重试与上报的状态
if ($ok) { exit 0 } else { exit 1 }

