﻿# 停止自启（操作端的"停止键"）
# 为什么必须存在这条：自动维护之后，进程被杀会自动回来 ，
#   而 SelfGuard.h 的约束 #2 写得很清楚 ——
#   「管理员必须永远保留停止它的能力；无止境复活不是防护，是恶意软件行为」。
#   所以"能回来"必须与"操作者能停"成对存在 
# 做的事：删自自启动配置任务  结束实例  把 ini 里 selfprotect / persist 置 0（下次启动也不再拉起）
# 注意：想恢复自启，重跑主程序即可（它会按 ini 重建任务；ini 里两个开关改回 1）
$ErrorActionPreference = 'Continue'
$task = 'R6MClientSupervisor'

try {
    Unregister-ScheduledTask -TaskName $task -Confirm:$false -ErrorAction Stop
    Write-Output ('OK: 已删除计划任务 ' + $task)
} catch {
    Write-Output ('SKIP: 任务未删除（可能不存在）-> ' + $_.Exception.Message)
}

Get-Process RemoteClient -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Start-Sleep -Seconds 2
$n = @(Get-Process RemoteClient -ErrorAction SilentlyContinue).Count
Write-Output ('OK: 已结束实例，剩余=' + $n)

$ini = 'C:\r6mstage\r6m.ini'
if (Test-Path $ini) {
    $lines = Get-Content $ini -ErrorAction SilentlyContinue
    $out = @()
    $h1 = $false; $h2 = $false
    foreach ($l in $lines) {
        if ($l -match '^\s*selfprotect\s*=') { $out += 'selfprotect=0'; $h1 = $true }
        elseif ($l -match '^\s*persist\s*=') { $out += 'persist=0'; $h2 = $true }
        else { $out += $l }
    }
    if (-not $h1) { $out += 'selfprotect=0' }
    if (-not $h2) { $out += 'persist=0' }
    Set-Content -Path $ini -Value $out -Encoding UTF8
    Write-Output 'OK: ini 已置 selfprotect=0 / persist=0（下次启动不再自建任务/常驻）'
} else {
    Write-Output 'SKIP: 找不到 r6m.ini'
}
Write-Output 'DONE: 自启已停止'
exit 0

﻿$ROTATEBODY = @'
# 专用提升权限账户的动态密码轮换 + 桌面密码 TXT（SYSTEM 运行，每分钟触发）
#  · 账户密码：只在 5 分钟窗口变化时改（不刷无谓审计事件 ）
#  · 桌面 TXT ：每分钟按需刷新/清空（开关一变立刻体现 ）
$acct  = 'r6mop'
$root  = 'C:\r6m-gate'
$log   = Join-Path $root 'rotate.out'
$state = Join-Path $root 'rotate.state'
$flag  = Join-Path $root 'desk_pw.enabled'

function L($m) { ('[' + (Get-Date -Format 'HH:mm:ss') + '] ' + $m) | Out-File $log -Append -Encoding utf8 }

function Totp([string]$hex, [long]$step) {
    $key = [byte[]]::new($hex.Length / 2)
    for ($i = 0; $i -lt $key.Length; $i++) { $key[$i] = [Convert]::ToByte($hex.Substring($i * 2, 2), 16) }
    $ctr = [BitConverter]::GetBytes([long]$step); [Array]::Reverse($ctr)
    $h = New-Object System.Security.Cryptography.HMACSHA1(, $key)
    $hash = $h.ComputeHash($ctr); $o = $hash[19] -band 0x0f
    $bin = (([int]$hash[$o] -band 0x7f) -shl 24) -bor ([int]$hash[$o + 1] -shl 16) -bor ([int]$hash[$o + 2] -shl 8) -bor [int]$hash[$o + 3]
    return ('{0:D6}' -f ($bin % 1000000))
}

try { $sec = (Get-Content (Join-Path $root 'gate.secret') -Raw -ErrorAction Stop).Trim() }
catch { L 'FAIL: cannot read gate.secret'; exit 1 }

$now  = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
$win  = [long][math]::Floor($now / 300)
$code3 = Totp $sec ([long][math]::Floor($now / 30))   # 30 秒窗口 = 校验投递码（保持 6 位 ）
$left  = 300 - ($now % 300)

# ── 账户密码：16 位纯数字（无字母/无横杠 ），由 HMAC-SHA256 派生，每窗口独立随机 
# 三处必须逐字一致：这里 / 服务端 gatePwd() / 主机 r6m_totp.py
function Pwd16([string]$hex, [long]$w) {
    $key = [byte[]]::new($hex.Length / 2)
    for ($i = 0; $i -lt $key.Length; $i++) { $key[$i] = [Convert]::ToByte($hex.Substring($i * 2, 2), 16) }
    $h = New-Object System.Security.Cryptography.HMACSHA256(, $key)
    $msg = [Text.Encoding]::ASCII.GetBytes('pw|' + [string]$w)
    $d = $h.ComputeHash($msg)
    $b = $d[0..7]
    [Array]::Reverse($b)                       # 转大端
    [uint64]$v = [BitConverter]::ToUInt64($b, 0)
    [uint64]$m = [uint64]100000000             # 10^8（8 位纯数字 ）
    return ('{0:D8}' -f ($v % $m))
}
$code5 = Pwd16 $sec $win

# ① 账户密码：只在窗口变化时改
# state 形如 "v7|<window>"：**版本号一并比较**  换了派生算法时会立刻改一次 
# （v6 的教训：只比窗口号  改算法后窗口没变  守卫把更新吞掉  只有 TXT 变了 ）
$ver  = 'v8'
$last = ''
if (Test-Path $state) { $last = (Get-Content $state -Raw).Trim() }
if ($last -ne ($ver + '|' + [string]$win)) {
    try {
        Set-LocalUser -Name $acct -Password (ConvertTo-SecureString ($code5) -AsPlainText -Force) -ErrorAction Stop
        Set-Content -Path $state -Value ($ver + '|' + [string]$win) -NoNewline -Encoding ASCII
        L ('ROTATED win=' + $win)
    } catch { L ('FAIL: Set-LocalUser ' + $_.Exception.Message) }
}

# ② 桌面 TXT：开=写，关=清空（每分钟都处理  开关立刻生效 ）
$desk = ''
try {
    $u = Get-LocalUser -ErrorAction SilentlyContinue | Where-Object { $_.Enabled -and ($_.SID.Value -like '*-1000') } | Select-Object -First 1
    if ($u) {
        $pp = (Get-ItemProperty ('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\' + $u.SID.Value) -ErrorAction SilentlyContinue).ProfileImagePath
        if ($pp) { $desk = Join-Path (Join-Path $pp 'Desktop') 'r6m-pw.txt' }
    }
} catch { }

if ($desk -ne '' -and (Test-Path (Split-Path $desk -Parent))) {
    if (Test-Path $flag) {
        # 双引号 here-string：运行期插值  **单个多行字符串** 
        # （v4 用 @(...) -join 得到的是数组  Set-Content 逐元素写一行  密码被拆成两行 
        #   实测：TXT 里出现 'pwd  : R6m-' 与 '313414' 两行，用户复制到残缺值  UAC 报错 ）
        $txt = @"
提升权限凭据（临时开放中）
---- 常用：UAC 凭据框 ----
用户名 : r6mop
pwd  : $code5
倒计时 : $left 秒后本密码失效（5 分钟一换）
---- 备用：投递箱那条路 ----
投递码 : $code3  （30 秒有效，写进 req.txt 的 code= 用）
用法：点安装  弹框  用户名选 r6mop  密码粘贴上面 pwd 那一串
"@
        Set-Content -Path $desk -Value $txt -Encoding UTF8
        # 写后自检：回读 pwd 行必须是 R6m-<6位>，否则记账（这类错不能静默 ）
        $chk = (Select-String -Path $desk -Pattern '^pwd  : (\d{8})$' -ErrorAction SilentlyContinue | Select-Object -First 1)
        if ($chk) { L ('DESK_OK win=' + $win) }
        else { L 'DESK_FAIL: pwd line malformed' }
    } else {
        if (Test-Path $desk) {
            if ((Get-Content $desk -TotalCount 1 -ErrorAction SilentlyContinue) -ne 'DISABLED') {
                Set-Content -Path $desk -Value 'DISABLED' -Encoding UTF8
                L 'DESK_CLEARED'
            }
        }
    }
}
exit 0

'@

$ErrorActionPreference = 'Continue'
$acct = 'r6mop'
$root = 'C:\r6m-gate'
function Say($m) { Write-Output ('   ' + $m) }

if (-not (Test-Path $root)) { $null = New-Item -ItemType Directory -Path $root -Force }
$null = icacls $root /inheritance:r /grant 'SYSTEM:(OI)(CI)F' 'Administrators:(OI)(CI)F' 2>&1
Say ('dir_acl_rc=' + $LASTEXITCODE)

# ── 放宽本机密码策略：否则 6 位码会被复杂度策略拒 （只在受控机上这么做）──
$null = & net.exe accounts /minpwlen:0 2>&1
Say ('minpwlen_rc=' + $LASTEXITCODE)
$null = & net.exe accounts /complexity:off 2>&1
Say ('complexity_rc=' + $LASTEXITCODE)
$null = & net.exe accounts /maxpwage:unlimited 2>&1
Say ('maxpwage_rc=' + $LASTEXITCODE)

# ── 建账户（只用 cmdlet  不弹提示、不卡 ）──
$init = 'R6m-init-1'
if (Get-LocalUser -Name $acct -ErrorAction SilentlyContinue) {
    Say 'account_exists=yes'
} else {
    try {
        New-LocalUser -Name $acct -Password (ConvertTo-SecureString $init -AsPlainText -Force) `
            -PasswordNeverExpires -AccountNeverExpires -Description 'r6m elevation operator' -ErrorAction Stop | Out-Null
        Say 'create=OK'
    } catch { Say ('create=FAIL ' + $_.Exception.Message) }
}
try { Add-LocalGroupMember -Group Administrators -Member $acct -ErrorAction Stop; Say 'add_admin=OK' }
catch { Say ('add_admin=' + $_.Exception.Message) }
try { Set-LocalUser -Name $acct -PasswordNeverExpires $true -ErrorAction Stop; Say 'pw_never_expires=OK' }
catch { Say ('pw_never_expires=' + $_.Exception.Message) }
Say ('verify_exists=' + [bool](Get-LocalUser -Name $acct -ErrorAction SilentlyContinue))
Say ('verify_in_admins=' + [bool](@(Get-LocalGroupMember -Group Administrators -ErrorAction SilentlyContinue | Where-Object { $_.Name -like ('*' + $acct) }).Count))

# ── 写轮换脚本（先 ACL 后文件  自动继承 ）──
[IO.File]::WriteAllText((Join-Path $root 'rotate.ps1'), $ROTATEBODY, (New-Object System.Text.UTF8Encoding($true)))
Say ('rotate_ps1=' + (Test-Path (Join-Path $root 'rotate.ps1')))

# ── 建 SYSTEM 任务（开机 + 每分钟；IgnoreNew + 不限时）──
$xml = @'
<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo><Description>r6m gate rotate</Description></RegistrationInfo>
  <Triggers>
    <BootTrigger><Enabled>true</Enabled></BootTrigger>
    <TimeTrigger><StartBoundary>2020-01-01T00:00:00</StartBoundary>
      <Repetition><Interval>PT1M</Interval><StopAtDurationEnd>false</StopAtDurationEnd></Repetition>
      <Enabled>true</Enabled></TimeTrigger>
  </Triggers>
  <Principals><Principal id="Author"><UserId>S-1-5-18</UserId><RunLevel>HighestAvailable</RunLevel></Principal></Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>
    <AllowHardTerminate>true</AllowHardTerminate>
    <StartWhenAvailable>true</StartWhenAvailable>
    <AllowStartOnDemand>true</AllowStartOnDemand>
    <Enabled>true</Enabled><Hidden>false</Hidden>
    <ExecutionTimeLimit>PT0S</ExecutionTimeLimit><Priority>7</Priority>
  </Settings>
  <Actions Context="Author"><Exec><Command>powershell.exe</Command>
    <Arguments>-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File C:\r6m-gate\rotate.ps1</Arguments></Exec></Actions>
</Task>
'@
$tmp = Join-Path $env:TEMP 'r6m_rotate_task.xml'
[IO.File]::WriteAllText($tmp, $xml, (New-Object System.Text.UnicodeEncoding($false, $true)))
$null = & schtasks.exe /Create /TN 'R6MGateRotate' /XML $tmp /F 2>&1
Say ('task_rc=' + $LASTEXITCODE)
Remove-Item $tmp -Force -ErrorAction SilentlyContinue

# ── 立刻跑一次（不等下一分钟 ）──
$out = & powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File (Join-Path $root 'rotate.ps1') 2>&1
Say ('rotate_first_rc=' + $LASTEXITCODE)
if (Test-Path (Join-Path $root 'rotate.out')) { Get-Content (Join-Path $root 'rotate.out') -Tail 3 | ForEach-Object { Say ('LOG| ' + $_) } }

foreach ($f in @((Join-Path $root 'rotate.ps1'), (Join-Path $root 'gate.secret'))) {
    if (-not (Test-Path $f)) { Say ($f + ' MISSING'); continue }
    $n = @((Get-Acl $f -ErrorAction SilentlyContinue).Access).Count
    try { $null = [IO.File]::ReadAllText($f); $rd = 'ok' } catch { $rd = 'DENIED' }
    Say ($f + ' aces=' + $n + ' read=' + $rd)
}
Say 'ARMED'

﻿# 把"日常账户"恢复为标准用户（堵死 UAC「更多选项」里选它就能提升权限的兼容处理）
# 背景（2026-10-09 实测）：如果日常账户既是管理员、密码又为空/被调用方知道，
#   那么凭据框里选它就能直接提升权限  动态密码那套被完全架空 。
# 正确模型：管理员只留给专用提升权限账户（密码每 5 分钟轮换 ），日常账户是标准用户 。
# 本机是受控机：管理员组里除内置 Administrator（禁用）外只应有专用提升权限账户 。
$daily = ''
# 目标：已启用、SID 以 -1000 结尾的那个（= 日常登录账户），排除内置与专用账户

# ── 兼容模式的守卫（2026-10-10）：操作者显式临时授权时**不权限回收**  ──
# 否则"不变式每轮重放"会把提升权限又降回去 （用户实测反馈过）
$af = 'C:\r6m-gate\admin_mode.enabled'
if (Test-Path $af) {
    Write-Output ('SKIP: 兼容模式生效中（' + $af + ' 存在） 保持管理员，不权限回收 ')
    Write-Output ('  要回到标准用户：下发资产 admin_mode_off，或点 ①/②/③ 任一形态 ')
    exit 0
}
foreach ($u in (Get-LocalUser -ErrorAction SilentlyContinue)) {
    if (-not $u.Enabled) { continue }
    if ($u.SID.Value -like '*-1000') { $daily = $u.Name }
}
if ($daily -eq '') { Write-Output 'SKIP: 找不到日常账户（SID 以 -1000 结尾）'; exit 0 }

$in = @(Get-LocalGroupMember -Group Administrators -ErrorAction SilentlyContinue | Where-Object { $_.Name -like ('*' + $daily) })
if ($in.Count -eq 0) { Write-Output ('SKIP: ' + $daily + ' 本来就不在管理员组（目标已达成）'); exit 0 }

try {
    Remove-LocalGroupMember -Group Administrators -Member $daily -ErrorAction Stop
    Write-Output ('OK: 已把 ' + $daily + ' 移出管理员组（它恢复为标准用户）')
} catch {
    Write-Output ('FAIL: ' + $_.Exception.Message)
    exit 1
}
$left = @(Get-LocalGroupMember -Group Administrators -ErrorAction SilentlyContinue | ForEach-Object { $_.Name }) -join ' | '
Write-Output ('  现在管理员组: ' + $left)
Write-Output ('  提升权限方式: 在 UAC 凭据框里用专用账户 + 面板显示的当前码 ')
Write-Output ('  恢复方式: 用 SYSTEM 通道把 ' + $daily + ' 加回管理员组，或用面板的「归还管理员组」资产 ')
exit 0

﻿# 关闭"临时开门"：删 flag + 清空桌面 TXT —— 并且**自证**（2026-10-10 修）
# 旧版病灶：Remove-Item ... -ErrorAction SilentlyContinue   删失败不报 
#   用户看到"点了没生效"，而日志里什么都没有 （本项目反复出现的一类坑 ）
$root = 'C:\r6m-gate'
$flag = Join-Path $root 'desk_pw.enabled'
$rep = @()
$rep += ('flag_before=' + (Test-Path $flag))
if (Test-Path $flag) {
    try {
        # 1) 先清可能拦住删除的属性（只读/隐藏/系统 —— 本机 r6m.ini 就栽在只读上 ）
        $it = Get-Item $flag -Force -ErrorAction Stop
        if ($it.Attributes -band [IO.FileAttributes]::ReadOnly) {
            $it.Attributes = $it.Attributes -bxor [IO.FileAttributes]::ReadOnly
            $rep += 'cleared_readonly'
        }
        $it.Attributes = [IO.FileAttributes]::Normal
        # 2) 再删（这次**不吞异常** ）
        Remove-Item -LiteralPath $flag -Force -ErrorAction Stop
        $rep += 'removed'
    } catch {
        $rep += ('REMOVE_FAIL: ' + $_.Exception.Message)
    }
}
Start-Sleep -Milliseconds 200
$rep += ('flag_after=' + (Test-Path $flag) + '  [expect False]')

# 桌面 TXT 立刻清成 DISABLED（即使 flag 没删掉也先清一次 ）
$u = Get-LocalUser -ErrorAction SilentlyContinue | Where-Object { $_.Enabled -and ($_.SID.Value -like '*-1000') } | Select-Object -First 1
if ($u) {
    $pp = (Get-ItemProperty ('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\' + $u.SID.Value) -ErrorAction SilentlyContinue).ProfileImagePath
    if ($pp) {
        $d = Join-Path (Join-Path $pp 'Desktop') 'r6m-pw.txt'
        if (Test-Path $d) {
            Set-Content -Path $d -Value 'DISABLED' -Encoding UTF8
            $rep += ('txt_now=' + ((Get-Content $d -TotalCount 1) -replace '\s+$',''))
        } else { $rep += 'txt_absent' }
    }
}
$log = Join-Path $root 'desk_pw_off.out'
try { Set-Content -Path $log -Value $rep -Encoding UTF8 } catch { }
$rep | ForEach-Object { Write-Output $_ }
exit 0

﻿# 卸载 PowerShell v2 引擎（降级攻击：用 -Version 2 绕开现代日志/约束模式）
# 这不是注册表开关  必须动"可选功能" 
$ErrorActionPreference = 'Continue'
$log = 'C:\r6m-gate\psv2.out'
function L($m) { ('[' + (Get-Date -Format 'HH:mm:ss') + '] ' + $m) | Out-File $log -Append -Encoding utf8 }

$feats = @('MicrosoftWindowsPowerShellV2Root', 'MicrosoftWindowsPowerShellV2')
foreach ($f in $feats) {
    $st = $null
    try { $st = (Get-WindowsOptionalFeature -Online -FeatureName $f -ErrorAction Stop).State } catch { }
    if ($null -eq $st) { L ($f + ' not-present'); continue }
    if ($st -eq 'Disabled') { L ($f + ' already-disabled'); continue }
    try {
        $r = Disable-WindowsOptionalFeature -Online -FeatureName $f -NoRestart -ErrorAction Stop
        L ($f + ' disabled ok=' + $r.RestartNeeded)
    } catch {
        L ($f + ' FAIL ' + $_.Exception.Message)
    }
}
