﻿# 开启关键审核（终版  用实测真名，枚举仅兜底）
# 实测(2026-10-10)：中文系统 auditpol 子类别真名 ——
#   进程创建  / **登录**（"登录/注销"是分组标题，/set 不认  rc=87）/ 特殊登录  / **账户锁定**（不是"帐户"）
$log = 'C:\r6m-gate\audit_enable.out'
$rep = @()

# 兜底用的实际名单
$list = (& auditpol.exe /list /subcategory:* 2>&1 | Out-String)
$names = @()
foreach ($line in ($list -split "`n")) {
    $t = $line.Trim()
    if ($t -ne '' -and $t -notmatch '^子类别|^Subcategory') { $names += $t }
}
$rep += ('subcategory_count=' + $names.Count)

function TrySet([string]$nm) {
    if ($nm -eq '') { return @($false, 999, 999) }
    $null = & auditpol.exe /set /subcategory:"$nm" /success:enable 2>&1; $rc1 = $LASTEXITCODE
    $null = & auditpol.exe /set /subcategory:"$nm" /failure:enable 2>&1; $rc2 = $LASTEXITCODE
    return @(($rc1 -eq 0 -or $rc2 -eq 0), $rc1, $rc2)
}
function Pick([string[]]$cands, [string]$kw) {
    foreach ($c in $cands) { if ($names -contains $c) { return $c } }
    if ($kw -ne '') {
        $h = $names | Where-Object { $_ -like ('*' + $kw + '*') } | Select-Object -First 1
        if ($h) { return $h }
    }
    return ''
}

# 候选顺序 = 实测有效的真名在前 
$targets = @(
  @{ want = 'process'; cands = @('进程创建');                              kw = '进程创建' },
  @{ want = 'logon';   cands = @('登录', '登录/注销');                      kw = '' },
  @{ want = 'special'; cands = @('特殊登录');                              kw = '特殊登录' },
  @{ want = 'lockout'; cands = @('账户锁定', '帐户锁定', '账户锁定策略');     kw = '户锁定' }
)
foreach ($t in $targets) {
    $nm = Pick $t.cands $t.kw
    if ($nm -eq '') { $rep += ('NOTFOUND ' + $t.want); continue }
    $r = TrySet $nm
    if ($r[0]) { $rep += ('OK   [' + $t.want + '] ' + $nm + '  rc=' + $r[1] + '/' + $r[2]) }
    else {
        # 兜底：逐个试名单里像它的（不再靠猜 ）
        $alt = $names | Where-Object { $_ -like ('*' + $t.want + '*') -or ($t.kw -ne '' -and $_ -like ('*' + $t.kw + '*')) } | Select-Object -First 3
        $done = $false
        foreach ($a in $alt) {
            $r2 = TrySet $a
            if ($r2[0]) { $rep += ('OK   [' + $t.want + '] ' + $a + ' (兜底命中, rc=' + $r2[1] + '/' + $r2[2] + ')'); $done = $true; break }
        }
        if (-not $done) { $rep += ('FAIL [' + $t.want + '] ' + $nm + ' rc=' + $r[1] + '/' + $r[2] + ' 且兜底全败') }
    }
}
# 复核
$cur = (& auditpol.exe /get /category:* 2>&1 | Out-String)
foreach ($k in @('进程创建', '登录', '特殊登录', '账户锁定')) {
    $line = ($cur -split "`n" | Where-Object { $_ -match [regex]::Escape($k) } | Select-Object -First 1)
    if ($line) { $rep += ('CHECK ' + ($line -replace '\s+', ' ').Trim()) }
}
try { Set-Content -Path $log -Value $rep -Encoding UTF8 } catch { }
$rep | ForEach-Object { Write-Output $_ }
exit 0

