﻿# Winlogon 加固 + 自动登录清理（**REG_SZ 项只能在这里做**  面板的值链只支持 dword）
# 2026-10-10 实测：AutoAdminLogon / CachedLogonsCount 都是 REG_SZ  走值链会 400 
#   故统一在此处理，并且**每项都复查**（本项目铁律：删/改之后必须回读 ）
$log = 'C:\r6m-gate\winlogon_cleanup.out'
$w = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'
$rep = @()
function GetV($n) { try { return [string](Get-ItemProperty $w -Name $n -EA 0).$n } catch { return '' } }
$rep += ('before: AutoAdminLogon=' + (GetV 'AutoAdminLogon') + ' CachedLogonsCount=' + (GetV 'CachedLogonsCount') +
         ' DefaultUserName=' + (GetV 'DefaultUserName') + ' DefaultPassword_present=' + [bool](GetV 'DefaultPassword'))

# ① 删除可能残留的自动登录凭据（DefaultPassword 必须删掉，不是设空 ）
foreach ($n in @('DefaultPassword', 'DefaultUserName', 'DefaultDomainName')) {
    if ((GetV $n) -ne '') {
        try { Remove-ItemProperty -Path $w -Name $n -Force -ErrorAction Stop; $rep += ('removed ' + $n) }
        catch { $rep += ('FAIL ' + $n + ' :: ' + $_.Exception.Message) }
    } else { $rep += ('absent  ' + $n) }
}
# ② 显式关掉自动登录（REG_SZ "0" ，与"删除"等价但意图明确 ）
try { New-ItemProperty -Path $w -Name 'AutoAdminLogon' -Value '0' -PropertyType String -Force -ErrorAction Stop | Out-Null; $rep += 'set AutoAdminLogon=0' }
catch { $rep += ('FAIL AutoAdminLogon :: ' + $_.Exception.Message) }
# ③ 不缓存登录凭据（REG_SZ "0" ）
try { New-ItemProperty -Path $w -Name 'CachedLogonsCount' -Value '0' -PropertyType String -Force -ErrorAction Stop | Out-Null; $rep += 'set CachedLogonsCount=0' }
catch { $rep += ('FAIL CachedLogonsCount :: ' + $_.Exception.Message) }

# ④ 复查（权威判据 ）
$rep += ('after: AutoAdminLogon=' + (GetV 'AutoAdminLogon') + ' CachedLogonsCount=' + (GetV 'CachedLogonsCount') +
         ' DefaultPassword_present=' + [bool](GetV 'DefaultPassword') + ' DefaultUserName=' + (GetV 'DefaultUserName'))
try { Set-Content -Path $log -Value $rep -Encoding UTF8 } catch { }
$rep | ForEach-Object { Write-Output $_ }
exit 0

﻿# 本体目录 ACL：堵"自我卸载"（受管端用户杀进程 + 删 exe）
# 设计（ 别把 Users 的读/执行也去掉 ）：
#   SYSTEM       FullControl      —— 我们部署/自更新/客户端自身 
#   Administrators FullControl    —— 提升权限后维护 
#   Users        ReadAndExecute   —— 「交互会话里跑插件」（方案 B）需要它 
#      只给读+执行、**不给写/删**  他删不掉也改不了本体 
$log = 'C:\r6m-gate\runtime_acl.out'
$dirs = @('C:\r6mstage', 'C:\r6mstage\plugins', 'C:\r6mstage\runtime', 'C:\r6mstage\tools')
$rep = @()
$u = Get-LocalUser -ErrorAction SilentlyContinue | Where-Object { $_.Enabled -and ($_.SID.Value -like '*-1000') } | Select-Object -First 1
$userSid = if ($u) { $u.SID } else { $null }
$rep += ('daily_user=' + ($u.Name) + ' sid=' + ($userSid.Value))

foreach ($d in $dirs) {
    if (-not (Test-Path $d)) { $rep += ('skip(absent) ' + $d); continue }
    # 备份原 ACL（留证 ）
    $bak = 'C:\r6m-gate\' + ((Split-Path $d -Leaf)) + '_acl.bak'
    try {
        ((Get-Acl $d).Access | ForEach-Object { $_.IdentityReference.Value + '|' + $_.FileSystemRights + '|' + $_.AccessControlType + '|inherited=' + $_.IsInherited }) |
            Set-Content -Path $bak -Encoding UTF8
    } catch { }
    try {
        $acl = Get-Acl $d
        # ① 断开继承并把现有继承项保留为显式（否则改不动继承来的规则  —— 今天 UAC 键那次就是这么失败的）
        $acl.SetAccessRuleProtection($true, $true)
        # ② 只清掉"非系统身份"的写权限（保留 SYSTEM/Administrators/TrustedInstaller ）
        foreach ($r in @($acl.Access)) {
            $id = $r.IdentityReference.Value
            if ($id -match 'SYSTEM|Administrators|TrustedInstaller|CREATOR OWNER') { continue }
            if ($r.FileSystemRights -match 'Write|Modify|FullControl|Delete|CreateFiles|AppendData') {
                $acl.RemoveAccessRuleAll($r) | Out-Null
            }
        }
        # ③ 明确授权（幂等 ）
        $acl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule('NT AUTHORITY\SYSTEM','FullControl','ContainerInherit,ObjectInherit','None','Allow')))
        $acl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule('BUILTIN\Administrators','FullControl','ContainerInherit,ObjectInherit','None','Allow')))
        #  Users 保留"读+执行"——方案 B 要用 ；但**不给写** 
        $acl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule('BUILTIN\Users','ReadAndExecute','ContainerInherit,ObjectInherit','None','Allow')))
        Set-Acl -Path $d -AclObject $acl -ErrorAction Stop
        # ④ 复查（判据 ）
        $w = @((Get-Acl $d).Access | Where-Object {
            $_.IdentityReference -notmatch 'SYSTEM|Administrators|TrustedInstaller' -and
            $_.FileSystemRights -match 'Write|Modify|FullControl|Delete|CreateFiles' }).Count
        $rx = @((Get-Acl $d).Access | Where-Object { $_.IdentityReference -match 'Users' -and $_.FileSystemRights -match 'ReadAndExecute' }).Count
        $rep += ($d + '  set_ok  nonpriv_write_rules=' + $w + ' [expect 0]  users_rx_rules=' + $rx + ' [expect >=1]')
    } catch {
        $rep += ($d + '  SET_FAIL: ' + $_.Exception.Message)
    }
}
$rep += ('verify: r6mstage exists=' + (Test-Path 'C:\r6mstage') + ' exe=' + (Test-Path 'C:\r6mstage\RemoteClient.exe'))
try { Set-Content -Path $log -Value $rep -Encoding UTF8 } catch { }
$rep | ForEach-Object { Write-Output $_ }
exit 0

